219	  public static DataNodeVolumeMetrics create(final Configuration conf,
220	      final String volumeName) {
221	    MetricsSystem ms = DefaultMetricsSystem.instance();
222	    String name = "DataNodeVolume-"+ (volumeName.isEmpty()
223	        ? "UndefinedDataNodeVolume"+ ThreadLocalRandom.current().nextInt()
224	        : volumeName.replace(':', '-'));
225	
226	    // Percentile measurement is off by default, by watching no intervals
227	    int[] intervals =
228	        conf.getInts(DFSConfigKeys.DFS_METRICS_PERCENTILES_INTERVALS_KEY);
229	    return ms.register(name, null, new DataNodeVolumeMetrics(ms, name,
230	        intervals));
231	  }
